// SOUNDS - the ONE place that plays sound effects.   playSound('pop')
// SOUND_ENABLED / setSoundEnabled() is the master switch: when it is off, effects AND the voice
// (speech.js checks it too) are silent. A new effect stops the previous one, so they never pile up.
// The files are generated by scripts/makeSounds.js; replace them with real recordings of the same name.
// There is no "wrong" sound on purpose: hints are only the buddy's gentle voice.

import { createAudioPlayer, setAudioModeAsync } from 'expo-audio';

export const SOUND_ENABLED = true;

export const SOUND_FILES = {
  pop: require('../../../assets/sounds/pop.wav'),
  whoosh: require('../../../assets/sounds/whoosh.wav'),
  boing: require('../../../assets/sounds/boing.wav'),
  sparkle: require('../../../assets/sounds/sparkle.wav'),
  tada: require('../../../assets/sounds/tada.wav'),
  cheerBell: require('../../../assets/sounds/cheer-bell.wav'),
};

const VOLUME = { whoosh: 0.35, default: 0.6 };

let enabled = SOUND_ENABLED;
let modeReady = false;
let current = null;
const players = {};

export function setSoundEnabled(value) {
  enabled = Boolean(value);
  if (!enabled) stopSounds();
}

export function soundEnabled() {
  return enabled;
}

function getPlayer(name) {
  if (!players[name]) {
    const player = createAudioPlayer(SOUND_FILES[name]);
    player.volume = VOLUME[name] || VOLUME.default;
    players[name] = player;
  }
  return players[name];
}

export function playSound(name) {
  if (!enabled || !SOUND_FILES[name]) return;
  try {
    if (!modeReady) {
      modeReady = true;
      setAudioModeAsync({ playsInSilentMode: true, interruptionMode: 'mixWithOthers' }).catch(() => {});
    }
    const player = getPlayer(name);
    if (current && current !== player) current.pause();
    current = player;
    player.seekTo(0).catch(() => {});
    player.play();
  } catch (error) {
    // A sound effect is a nice-to-have: never let it break the lesson.
  }
}

export function stopSounds() {
  try {
    if (current) current.pause();
  } catch (error) {
    // ignore
  }
  current = null;
}
